package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when an attempt is made to create an {@code Owner} after the maximum number of
 * owners allowed to be registered on a single day has already been reached. Handled by
 * {@link ExceptionControllerAdvice} as an HTTP 400 Bad Request.
 */
public class DailyOwnerRegistrationLimitException extends RuntimeException {

    public DailyOwnerRegistrationLimitException(String message) {
        super(message);
    }
}

